  "content": "250|  const commitManual = (
251|    nextEndpoint: string,
252|    nextActionType: typeof ACTION_OPTIONS[number],
253|    nextPayloadEntries: PayloadEntry[],
254|    nextUrlParams: Record<string, string>,
255|    nextHeaders: Record<string, string>,
256|    nextStoreWritePath: string,
257|  ) => {
258|    const trimmedEndpoint = nextEndpoint.trim();
259|    const trimmedStoreWritePath = nextStoreWritePath.trim();
260|
261|    if (trimmedEndpoint.length === 0 && trimmedStoreWritePath.length === 0) {
262|      clearBinding();
263|      return;
264|    }
265|
266|    if (trimmedEndpoint.length === 0) {
267|      dispatch({
268|        type: 'set-node-binding',
269|        nodeId: node.id,
270|        bindingKey,
271|        definition: {
272|          sourceType: 'store',
273|          bindingRole: 'event',
274|          targetEvent,
275|          storeWritePath: trimmedStoreWritePath,
276|        },
277|      });
278|      return;
279|    }
280|
281|    dispatch({
282|      type: 'set-node-binding',
283|      nodeId: node.id,
284|      bindingKey,
285|      definition: createEventBindingDefinition(
286|        targetEvent,
287|        trimmedEndpoint,
288|        nextActionType,
289|        payloadEntriesToRecord(nextPayloadEntries),
290|        {
291|          urlParams: nextUrlParams,
292|          headers: nextHeaders,
293|          storeWritePath: trimmedStoreWritePath.length > 0 ? trimmedStoreWritePath : undefined,
294|        },
295|      ),
296|    });
297|  };
298|
299|  const updatePayloadEntries = (nextEntries: PayloadEntry[]) => {
300|    setPayloadEntries(nextEntries);
301|    if (actionMode === 'manual' && (endpoint.trim().length > 0 || storeWritePath.trim().length > 0)) {
302|      commitManual(endpoint, actionType, nextEntries, urlParams, headers, storeWritePath);
303|    }
304|  };
305|
306|  const handleActionModeChange = (nextMode: ActionMode) => {
307|    setActionMode(nextMode);
308|
309|    if (nextMode === 'none') {
310|      clearBinding();
311|      return;
312|    }
313|
314|    if (nextMode === 'regionSubmit') {
315|      commitRegionSubmit();
316|      return;
317|    }
318|
319|    if (nextMode === 'refreshDataSource') {
320|      commitRefreshDataSource(refreshDataSourceRef || dataSourceOptions[0]?.id || '');
321|      return;
322|    }
323|
324|    if (nextMode === 'dynamicActions') {
325|      const nonRefreshActions = trueActions.filter((action) => action.type !== 'refreshDataSource');
326|      commitDynamicActions(nonRefreshActions);
327|      return;
328|    }
329|
